#!/usr/bin/env python3
"""
Sets up Git pre-commit hooks to automate quality gates and governance.
Works for Windows (Git Bash) and Linux/macOS.
"""
import os
import sys
from pathlib import Path

def setup_hooks():
    git_dir = Path(".git")
    if not git_dir.exists():
        print("Error: Not a git repository.")
        return

    hook_path = git_dir / "hooks" / "pre-commit"
    
    hook_content = """#!/bin/bash
# Pre-commit hook generated by bank-agent-skills/scripts/setup_hooks.py
echo "--- Running Architectural Governance Gates ---"

# 1. Run Test Suite
PYTHONPATH=. pytest tests/
if [ $? -ne 0 ]; then
    echo "Tests failed. Commit aborted."
    exit 1
fi

# 2. Run Skills Lint
python3 scripts/skills_lint/engine.py .
if [ $? -ne 0 ]; then
    echo "Skills linting failed. Commit aborted."
    exit 1
fi

# 3. Run Link Lint
python3 scripts/links_lint.py
if [ $? -ne 0 ]; then
    echo "Link linting failed. Commit aborted."
    exit 1
fi

echo "--- Governance Gates Passed. Commit proceeding. ---"
"""
    
    with open(hook_path, "w", encoding="utf-8") as f:
        f.write(hook_content)
    
    # Make executable
    os.chmod(hook_path, 0o755)
    print(f"✓ Pre-commit hook installed at {hook_path}")
    print("Note: If you use GitLab CI, these checks are also mirrored in .gitlab-ci.yml for server-side validation.")

if __name__ == "__main__":
    setup_hooks()
